INSERT INTO `egg_variables` (`id`, `egg_id`, `name`, `description`, `env_variable`, `default_value`, `user_viewable`, `user_editable`, `rules`, `created_at`, `updated_at`) VALUES
(1, 1, 'Bungeecord Version', 'The version of Bungeecord to download and use.', 'BUNGEE_VERSION', 'latest', 1, 1, 'required|alpha_num|between:1,6', '2026-10-14 12:29:51', '2026-10-14 12:29:51'),
(2, 1, 'Bungeecord Jar File', 'The name of the Jarfile to use when running Bungeecord.', 'SERVER_JARFILE', 'bungeecord.jar', 1, 1, 'required|regex:/^([\\w\\d._-]+)(\\.jar)$/', '2026-10-14 12:29:51', '2026-10-14 12:29:51'),
(3, 2, 'Sponge Version', 'The version of SpongeVanilla to download and use.', 'SPONGE_VERSION', '1.12.2-7.3.0', 1, 1, 'required|regex:/^([a-zA-Z0-9.\\-_]+)$/', '2026-10-14 12:29:51', '2026-10-14 12:29:51'),
(4, 2, 'Server Jar File', 'The name of the Jarfile to use when running SpongeVanilla.', 'SERVER_JARFILE', 'server.jar', 1, 1, 'required|regex:/^([\\w\\d._-]+)(\\.jar)$/', '2026-10-14 12:29:51', '2026-10-14 12:29:51'),
(5, 3, 'Server Jar File', 'The name of the server jarfile to run the server with.', 'SERVER_JARFILE', 'server.jar', 1, 1, 'required|regex:/^([\\w\\d._-]+)(\\.jar)$/', '2026-10-14 12:29:51', '2026-10-14 12:29:51'),
(6, 3, 'Server Version', 'The version of Minecraft Vanilla to install. Use \"latest\" to install the latest version, or use \"snapshot\" to install the latest snapshot. Go to Settings > Reinstall Server to apply.', 'VANILLA_VERSION', 'latest', 1, 1, 'required|string|between:3,15', '2026-10-14 12:29:51', '2026-10-14 12:29:51'),
(7, 4, 'Server Jar File', 'The name of the Jarfile to use when running Forge version below 1.17.', 'SERVER_JARFILE', 'server.jar', 1, 1, 'required|regex:/^([\\w\\d._-]+)(\\.jar)$/', '2026-10-14 12:29:51', '2026-10-14 12:29:51'),
(8, 4, 'Minecraft Version', 'The version of minecraft you want to install for.\r\n\r\nLeaving latest will install the latest recommended version.', 'MC_VERSION', 'latest', 1, 1, 'required|string|max:9', '2026-10-14 12:29:51', '2026-10-14 12:29:51'),
(9, 4, 'Build Type', 'The type of server jar to download from forge.\r\n\r\nValid types are \"recommended\" and \"latest\".', 'BUILD_TYPE', 'recommended', 1, 1, 'required|string|in:recommended,latest', '2026-10-14 12:29:51', '2026-10-14 12:29:51'),
(10, 4, 'Forge Version', 'The full exact version.\r\n\r\nEx. 1.15.2-31.2.4\r\n\r\nOverrides MC_VERSION and BUILD_TYPE. If it fails to download the server files it will fail to install.', 'FORGE_VERSION', '', 1, 1, 'nullable|regex:/^[0-9\\.\\-]+$/', '2026-10-14 12:29:51', '2026-10-14 12:29:51'),
(11, 5, 'Minecraft Version', 'The version of minecraft to download. \r\n\r\nLeave at latest to always get the latest version. Invalid versions will default to latest.', 'MINECRAFT_VERSION', 'latest', 1, 1, 'nullable|string|max:20', '2026-10-14 12:29:51', '2026-10-14 12:29:51'),
(12, 5, 'Server Jar File', 'The name of the server jarfile to run the server with.', 'SERVER_JARFILE', 'server.jar', 1, 1, 'required|regex:/^([\\w\\d._-]+)(\\.jar)$/', '2026-10-14 12:29:51', '2026-10-14 12:29:51'),
(13, 5, 'Download Path', 'A URL to use to download a server.jar rather than the ones in the install script. This is not user viewable.', 'DL_PATH', '', 0, 0, 'nullable|string', '2026-10-14 12:29:51', '2026-10-14 12:29:51'),
(14, 5, 'Build Number', 'The build number for the paper release.\r\n\r\nLeave at latest to always get the latest version. Invalid versions will default to latest.', 'BUILD_NUMBER', 'latest', 1, 1, 'required|string|max:20', '2026-10-14 12:29:51', '2026-10-14 12:29:51'),
(15, 6, 'Game ID', 'The ID corresponding to the game to download and run using SRCDS.', 'SRCDS_APPID', '237410', 1, 0, 'required|regex:/^(237410)$/', '2026-10-14 12:29:51', '2026-10-14 12:29:51'),
(16, 6, 'Default Map', 'The default map to use when starting the server.', 'SRCDS_MAP', 'sinjar', 1, 1, 'required|regex:/^(\\w{1,20})$/', '2026-10-14 12:29:51', '2026-10-14 12:29:51'),
(17, 7, 'Game ID', 'The ID corresponding to the game to download and run using SRCDS.', 'SRCDS_APPID', '', 1, 0, 'required|numeric|digits_between:1,6', '2026-10-14 12:29:51', '2026-10-14 12:29:51'),
(18, 7, 'Game Name', 'The name corresponding to the game to download and run using SRCDS.', 'SRCDS_GAME', '', 1, 0, 'required|alpha_dash|between:1,100', '2026-10-14 12:29:51', '2026-10-14 12:29:51'),
(19, 7, 'Map', 'The default map for the server.', 'SRCDS_MAP', '', 1, 1, 'required|string|alpha_dash', '2026-10-14 12:29:51', '2026-10-14 12:29:51'),
