(24, 8, 'Admin Password', 'If specified, players must provide this password (via the in-game console) to gain access to administrator commands on the server.', 'ARK_ADMIN_PASSWORD', 'PleaseChangeMe', 1, 1, 'required|alpha_dash|between:1,100', '2026-10-14 12:29:51', '2026-10-14 12:29:51'),
(25, 8, 'Server Map', 'Available Maps: TheIsland, TheCenter, Ragnarok, ScorchedEarth_P, Aberration_P, Extinction, Valguero_P, Genesis, CrystalIsles, Gen2, Fjordur', 'SERVER_MAP', 'TheIsland', 1, 1, 'required|string|max:20', '2026-10-14 12:29:51', '2026-10-14 12:29:51'),
(26, 8, 'Server Name', 'ARK server name', 'SESSION_NAME', 'A Pterodactyl Hosted ARK Server', 1, 1, 'required|string|max:128', '2026-10-14 12:29:51', '2026-10-14 12:29:51'),
(27, 8, 'Rcon Port', 'ARK rcon port used by rcon tools.', 'RCON_PORT', '27020', 1, 1, 'required|numeric', '2026-10-14 12:29:51', '2026-10-14 12:29:51'),
(28, 8, 'Query Port', 'ARK query port used by steam server browser and ark client server browser.', 'QUERY_PORT', '27015', 1, 1, 'required|numeric', '2026-10-14 12:29:51', '2026-10-14 12:29:51'),
(29, 8, 'Auto-update server', 'This is to enable auto-updating for servers.\r\n\r\nDefault is 0. Set to 1 to update', 'AUTO_UPDATE', '0', 1, 1, 'required|boolean', '2026-10-14 12:29:51', '2026-10-14 12:29:51'),
(30, 8, 'Battle Eye', 'Enable BattleEye\r\n\r\n0 to disable\r\n1 to enable\r\n\r\ndefault=\"1\"', 'BATTLE_EYE', '1', 1, 1, 'required|boolean', '2026-10-14 12:29:51', '2026-10-14 12:29:51'),
(31, 8, 'App ID', 'ARK steam app id for auto updates. Leave blank to avoid auto update.', 'SRCDS_APPID', '376030', 1, 0, 'nullable|numeric', '2026-10-14 12:29:51', '2026-10-14 12:29:51'),
(32, 8, 'Additional Arguments', 'Specify additional launch parameters such as -crossplay. You must include a dash - and separate each parameter with space: -crossplay -exclusivejoin', 'ARGS', '', 1, 1, 'nullable|string', '2026-10-14 12:29:51', '2026-10-14 12:29:51'),
(33, 8, 'Mods', 'Specifies the order and which mods are loaded. ModIDs need to be comma-separated such as: ModID1,ModID2', 'MOD_ID', '', 1, 1, 'nullable|string', '2026-10-14 12:29:51', '2026-10-14 12:29:51'),
