(36, 9, 'Steam Account Token', 'The Steam Account Token required for the server to be displayed publicly.', 'STEAM_ACC', '', 1, 1, 'required|string|alpha_num|size:32', '2026-10-14 12:29:51', '2026-10-14 12:29:51'),
