(40, 10, 'Source AppID', 'Required for game to update on server restart. Do not modify this.', 'SRCDS_APPID', '4020', 0, 0, 'required|string|max:20', '2026-10-14 12:29:51', '2026-10-14 12:29:51'),
(41, 10, 'Workshop ID', 'The ID of your workshop collection (the numbers at the end of the URL)', 'WORKSHOP_ID', '', 1, 1, 'nullable|integer', '2026-10-14 12:29:51', '2026-10-14 12:29:51'),
(42, 10, 'Gamemode', 'The gamemode of your server.', 'GAMEMODE', 'sandbox', 1, 1, 'required|string', '2026-10-14 12:29:51', '2026-10-14 12:29:51'),
(43, 10, 'Max Players', 'The maximum amount of players allowed on your game server.', 'MAX_PLAYERS', '32', 1, 1, 'required|integer|max:128', '2026-10-14 12:29:51', '2026-10-14 12:29:51'),
(44, 10, 'Tickrate', 'The tickrate defines how fast the server will update each entity\'s location.', 'TICKRATE', '22', 1, 1, 'required|integer|max:100', '2026-10-14 12:29:51', '2026-10-14 12:29:51'),
(45, 10, 'Lua Refresh', '0 = disable Lua refresh,\r\n1 = enable Lua refresh', 'LUA_REFRESH', '0', 1, 1, 'required|boolean', '2026-10-14 12:29:51', '2026-10-14 12:29:51'),
(46, 11, 'Game ID', 'The ID corresponding to the game to download and run using SRCDS.', 'SRCDS_APPID', '232250', 1, 0, 'required|regex:/^(232250)$/', '2026-10-14 12:29:51', '2026-10-14 12:29:51'),
