(48, 11, 'Steam', 'The Steam Game Server Login Token to display servers publicly. Generate one at https://steamcommunity.com/dev/managegameservers', 'STEAM_ACC', '', 1, 1, 'required|string|alpha_num|size:32', '2026-10-14 12:29:51', '2026-10-14 12:29:51'),
(49, 12, 'Maximum Users', 'Maximum concurrent users on the mumble server.', 'MAX_USERS', '100', 1, 0, 'required|numeric|digits_between:1,5', '2026-10-14 12:29:51', '2026-10-14 12:29:51'),
(50, 13, 'Server Version', 'The version of Teamspeak 3 to use when running the server.', 'TS_VERSION', 'latest', 1, 1, 'required|string|max:6', '2026-10-14 12:29:51', '2026-10-14 12:29:51'),
(51, 13, 'File Transfer Port', 'The Teamspeak file transfer port', 'FILE_TRANSFER', '30033', 1, 0, 'required|integer|between:1025,65535', '2026-10-14 12:29:51', '2026-10-14 12:29:51'),
(52, 13, 'Query Port', 'The Teamspeak Query Port', 'QUERY_PORT', '10011', 1, 0, 'required|integer|between:1025,65535', '2026-10-14 12:29:51', '2026-10-14 12:29:51'),
(53, 13, 'Query Protocols', 'Comma separated list of protocols that can be used to connect to the ServerQuery | \r\nPossible values are raw, ssh and http | \r\nE.g.: raw,ssh,http', 'QUERY_PROTOCOLS_VAR', 'raw,http,ssh', 1, 1, 'required|string|max:12', '2026-10-14 12:29:51', '2026-10-14 12:29:51'),
(54, 13, 'Query SSH Port', 'TCP Port opened for ServerQuery connections using SSH', 'QUERY_SSH', '10022', 1, 0, 'required|integer|between:1025,65535', '2026-10-14 12:29:51', '2026-10-14 12:29:51'),
(55, 13, 'Query HTTP Port', 'TCP Port opened for ServerQuery connections using http', 'QUERY_HTTP', '10080', 1, 0, 'required|integer|between:1025,65535', '2026-10-14 12:29:51', '2026-10-14 12:29:51'),
(56, 13, 'Server Query Admin Password', 'The password for the server query admin user.', 'SERVERADMIN_PASSWORD', '', 1, 1, 'nullable|string|max:32', '2026-10-14 12:29:51', '2026-10-14 12:29:51'),
(57, 14, 'Server Name', 'The name of your server in the public server list.', 'HOSTNAME', 'A Rust Server', 1, 1, 'required|string|max:60', '2026-10-14 12:29:51', '2026-10-14 12:29:51'),
(58, 14, 'Modding Framework', 'The modding framework to be used: carbon, oxide, vanilla.\r\nDefaults to \"vanilla\" for a non-modded server installation.', 'FRAMEWORK', 'vanilla', 1, 1, 'required|in:vanilla,oxide,carbon', '2026-10-14 12:29:51', '2026-10-14 12:29:51'),
(59, 14, 'Level', 'The world file for Rust to use.', 'LEVEL', 'Procedural Map', 1, 1, 'required|string|max:20', '2026-10-14 12:29:51', '2026-10-14 12:29:51'),
(60, 14, 'Description', 'The description under your server title. Commonly used for rules & info. Use \\n for newlines.', 'DESCRIPTION', 'Powered by Pterodactyl', 1, 1, 'required|string', '2026-10-14 12:29:51', '2026-10-14 12:29:51'),
(61, 14, 'URL', 'The URL for your server. This is what comes up when clicking the \"Visit Website\" button.', 'SERVER_URL', 'http://pterodactyl.io', 1, 1, 'nullable|url', '2026-10-14 12:29:51', '2026-10-14 12:29:51'),
(62, 14, 'World Size', 'The world size for a procedural map.', 'WORLD_SIZE', '3000', 1, 1, 'required|integer', '2026-10-14 12:29:51', '2026-10-14 12:29:51'),
(63, 14, 'World Seed', 'The seed for a procedural map.', 'WORLD_SEED', '', 1, 1, 'nullable|string', '2026-10-14 12:29:51', '2026-10-14 12:29:51'),
(64, 14, 'Max Players', 'The maximum amount of players allowed in the server at once.', 'MAX_PLAYERS', '40', 1, 1, 'required|integer', '2026-10-14 12:29:51', '2026-10-14 12:29:51'),
(65, 14, 'Server Image', 'The header image for the top of your server listing.', 'SERVER_IMG', '', 1, 1, 'nullable|url', '2026-10-14 12:29:51', '2026-10-14 12:29:51'),
(66, 14, 'Query Port', 'Server Query Port. Can\'t be the same as Game\'s primary port.', 'QUERY_PORT', '27017', 1, 0, 'required|integer', '2026-10-14 12:29:51', '2026-10-14 12:29:51'),
(67, 14, 'RCON Port', 'Port for RCON connections.', 'RCON_PORT', '28016', 1, 0, 'required|integer', '2026-10-14 12:29:51', '2026-10-14 12:29:51'),
(68, 14, 'RCON Password', 'RCON access password.', 'RCON_PASS', '', 1, 1, 'required|regex:/^[\\w.-]*$/|max:64', '2026-10-14 12:29:51', '2026-10-14 12:29:51'),
(69, 14, 'Save Interval', 'Sets the server’s auto-save interval in seconds.', 'SAVEINTERVAL', '60', 1, 1, 'required|integer', '2026-10-14 12:29:51', '2026-10-14 12:29:51'),
(70, 14, 'Additional Arguments', 'Add additional startup parameters to the server.', 'ADDITIONAL_ARGS', '', 1, 1, 'nullable|string', '2026-10-14 12:29:51', '2026-10-14 12:29:51'),
(71, 14, 'App Port', 'Port for the Rust+ App. -1 to disable.', 'APP_PORT', '28082', 1, 0, 'required|integer', '2026-10-14 12:29:51', '2026-10-14 12:29:51'),
(72, 14, 'Server Logo', 'The circular server logo for the Rust+ app.', 'SERVER_LOGO', '', 1, 1, 'nullable|url', '2026-10-14 12:29:51', '2026-10-14 12:29:51'),
(73, 14, 'Custom Map URL', 'Overwrites the map with the one from the direct download URL. Invalid URLs will cause the server to crash.', 'MAP_URL', '', 1, 1, 'nullable|url', '2026-10-14 12:29:51', '2026-10-14 12:29:51');
